typedef struct {
  struct tree_statement_list_node *ptr;
  tree container;
} tree_stmt_iterator;

static inline tree_stmt_iterator
tsi_start (tree t)
{
  tree_stmt_iterator i;

  i.ptr = ((t)->stmt_list.head);
  i.container = t;

  return i;
}

static inline tree_stmt_iterator
tsi_last (tree t)
{
  tree_stmt_iterator i;

  i.ptr = ((t)->stmt_list.tail);
  i.container = t;

  return i;
}

static inline unsigned char
tsi_end_p (tree_stmt_iterator i)
{
  return i.ptr == 
/* # 89536 "gcc.c" 3 4 */
                 ((void *)0)
/* # 89536 "gcc.c" */
                     ;
}

static inline unsigned char
tsi_one_before_end_p (tree_stmt_iterator i)
{
  return i.ptr != 
/* # 89542 "gcc.c" 3 4 */
                 ((void *)0) 
/* # 89542 "gcc.c" */
                      && i.ptr->next == 
/* # 89542 "gcc.c" 3 4 */
                                        ((void *)0)
/* # 89542 "gcc.c" */
                                            ;
}

static inline void
tsi_next (tree_stmt_iterator *i)
{
  i->ptr = i->ptr->next;
}

static inline void
tsi_prev (tree_stmt_iterator *i)
{
  i->ptr = i->ptr->prev;
}

static inline tree *
tsi_stmt_ptr (tree_stmt_iterator i)
{
  return &i.ptr->stmt;
}

static inline tree
tsi_stmt (tree_stmt_iterator i)
{
  return i.ptr->stmt;
}

