static void
dump_generic_bb_buff (pretty_printer *buffer, basic_block bb,
        int indent, int flags)
{
  block_stmt_iterator bsi;
  tree stmt;
  int label_indent = indent - 2;

  if (label_indent < 0)
    label_indent = 0;

  dump_bb_header (buffer, bb, indent, flags);

  if (bb_ann (bb))
    dump_phi_nodes (buffer, bb, indent, flags);

  for (bsi = bsi_start (bb); !bsi_end_p (bsi); bsi_next (&bsi))
    {
      int curr_indent;

      stmt = bsi_stmt (bsi);

      curr_indent = ((enum tree_code) (stmt)->common.code) == LABEL_EXPR ? label_indent : indent;

      do { int i; for (i = 0; i<curr_indent; i++) pp_base_character ((buffer), ' '); } while (0);
      dump_generic_node (buffer, stmt, curr_indent, flags, 1);
      pp_base_newline ((buffer));
    }

  dump_implicit_edges (buffer, bb, indent, flags);

  if (flags & (1 << 5))
    dump_bb_end (buffer, bb, indent, flags);
}
